import { computed, type ComputedRef, type MaybeRefOrGetter, type Ref } from 'vue'
import { useNuxtApp, useWidgets } from '#imports'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore virtual module generated by this module's `setup()`
import { dashboards } from '#dashboard/registry'
import type { WidgetMeta } from '@frigear-nu/widget'
import type { DashboardLayout, DashboardPlatform, DashboardRegistryEntry } from '../../../types'
import { applyLayout, filterByPlatform, hideItem, moveItem, resetLayout, showItem, toggleCollapsed } from '../../shared/layout'
import { dashboardArea } from '../../shared/registry'
import { getDashboardItemIds } from '../utils/components'
import { useDashboardLayout } from './useDashboardLayout'
import { useDashboardPlatform } from './useDashboardPlatform'

/** A resolved item: its widget data, its dashboard data and its title translated. */
export type DashboardEntry = WidgetMeta & Omit<DashboardRegistryEntry, 'id'> & {
  /** The dashboard's name. */
  dashboard: string
  /** Whether the user collapsed it. */
  collapsed: boolean
}

export interface UseDashboard {
  /** The items to render: allowed for the viewer, on this platform, not hidden, in the user's order. */
  items: ComputedRef<DashboardEntry[]>
  /** The items the user hid, in their order. */
  hidden: ComputedRef<DashboardEntry[]>
  /** Ids of the collapsed items. */
  collapsed: ComputedRef<string[]>
  /** The user's layout of this dashboard. */
  layout: ComputedRef<DashboardLayout>
  /** Whether layout changes are saved for the user, not only kept for this session. */
  persisted: ComputedRef<boolean>
  /** Whether a layout change is being saved: disable the edit buttons meanwhile. */
  saving: Ref<boolean>
  platform: Ref<DashboardPlatform>
  /** Moves an item to `toIndex` among `items`. */
  move: (id: string, toIndex: number) => Promise<void>
  hide: (id: string) => Promise<void>
  show: (id: string) => Promise<void>
  toggleCollapsed: (id: string) => Promise<void>
  /** Back to the registered default. */
  reset: () => Promise<void>
  status: ReturnType<typeof useWidgets>['status']
  error: ReturnType<typeof useWidgets>['error']
  refresh: () => Promise<void>
}

/**
 * A dashboard's items, resolved for the current viewer: filtered by `permission` (the `widgets:filter` hook of
 * `@frigear-nu/widget`), by platform, and laid out in the user's order without the hidden ones. Plus the edits of the
 * layout. Await it on a page so the items render on the server.
 *
 * ```ts
 * const { items, hidden, move, hide, show, reset } = await useDashboard('crew.home')
 * ```
 */
export function useDashboard(name: string, context?: MaybeRefOrGetter<Record<string, unknown> | undefined>): UseDashboard & Promise<UseDashboard> {
  const nuxtApp = useNuxtApp()
  const i18n = nuxtApp.$i18n as { t: (key: string) => string } | undefined
  // `t` also resolves the fallback locale; it answers the key itself when no locale has it.
  const translate = (key: string | undefined, fallback: string | undefined) => {
    if (!key || !i18n) return fallback
    const text = i18n.t(key)
    return text && text !== key ? text : fallback
  }

  const platform = useDashboardPlatform()
  const registry: Record<string, DashboardRegistryEntry> = (dashboards as Record<string, Record<string, DashboardRegistryEntry>>)[name] ?? {}
  const widgets = useWidgets(dashboardArea(name), context)
  const { layout, persisted, saving, update } = useDashboardLayout(name)

  // Widget meta joined with the dashboard registry by id. An item missing from the registry was dropped at build
  // time (`when.module`), so it is left out here too.
  const available = computed<DashboardEntry[]>(() => {
    const collapsed = new Set(layout.value.collapsed)
    const joined = (widgets.data.value ?? []).flatMap((widget: WidgetMeta) => {
      const entry = registry[widget.id]
      if (!entry) return []
      const { id: _id, ...extra } = entry
      return [{
        ...widget,
        ...extra,
        title: translate(entry.titleKey, entry.title),
        dashboard: name,
        collapsed: collapsed.has(widget.id),
      }]
    })
    return filterByPlatform(joined, platform.value)
  })
  const applied = computed(() => applyLayout(available.value, layout.value))

  const items = computed(() => applied.value.items)
  const result: UseDashboard = {
    items,
    hidden: computed(() => applied.value.hidden),
    collapsed: computed(() => applied.value.collapsed),
    layout,
    persisted,
    saving,
    platform,
    // Within the full order of every item, so items of the other platform (or another viewer) keep their place.
    move: (id, toIndex) => update(current => moveItem(current, getDashboardItemIds(name), items.value.map(item => item.id), id, toIndex)),
    hide: id => update(current => hideItem(current, id)),
    show: id => update(current => showItem(current, id)),
    toggleCollapsed: id => update(current => toggleCollapsed(current, id)),
    reset: () => update(() => resetLayout()),
    status: widgets.status,
    error: widgets.error,
    refresh: () => widgets.refresh(),
  }

  // Like `useAsyncData`: usable as is, or awaited so the items are there before the page renders.
  const promise = Promise.resolve(widgets).then(() => result)
  return Object.assign(promise, result)
}
